    m_->u[0][1][2] = m_->index_ == 0 ? 0.0 : m_->lap[0][0] * m_->u[1][0][1] + m_->lap[0][1] * m_->u[1][0][2] + m_->lap[0][2] * 0.0 + (m_->lap[1][0] * m_->u[1][1][1] + m_->lap[1][1] * m_->u[1][1][2] + m_->lap[1][2] * 0.0) + (m_->lap[2][0] * m_->u[1][2][1] + m_->lap[2][1] * m_->u[1][2][2] + m_->lap[2][2] * 0.0);
    m_->u[0][2][0] = m_->index_ == 0 ? 0.0 : m_->lap[0][0] * 0.0 + m_->lap[0][1] * m_->u[1][1][0] + m_->lap[0][2] * m_->u[1][1][1] + (m_->lap[1][0] * 0.0 + m_->lap[1][1] * m_->u[1][2][0] + m_->lap[1][2] * m_->u[1][2][1]) + t1_;
    m_->u[0][2][1] = m_->index_ == 0 ? 0.0 : m_->lap[0][0] * m_->u[1][1][0] + m_->lap[0][1] * m_->u[1][1][1] + m_->lap[0][2] * m_->u[1][1][2] + (m_->lap[1][0] * m_->u[1][2][0] + m_->lap[1][1] * m_->u[1][2][1] + m_->lap[1][2] * m_->u[1][2][2]) + t1_;
    m_->u[0][2][2] = m_->index_ == 0 ? 0.0 : m_->lap[0][0] * m_->u[1][1][1] + m_->lap[0][1] * m_->u[1][1][2] + m_->lap[0][2] * 0.0 + (m_->lap[1][0] * m_->u[1][2][1] + m_->lap[1][1] * m_->u[1][2][2] + m_->lap[1][2] * 0.0) + t1_;
